def _w(name, slug, cost, dmg, dtype, weight, props, cat):
    return {"name": name, "slug": slug, "data": {"type": "weapon", "category": cat, "cost": cost, "damage": dmg, "damage_type": dtype, "weight": weight, "properties": props}}

def _a(name, slug, cost, ac, weight, cat, stealth=False, str_req=0):
    return {"name": name, "slug": slug, "data": {"type": "armor", "category": cat, "cost": cost, "ac": ac, "weight": weight, "stealth_disadvantage": stealth, "str_req": str_req}}

def _g(name, slug, cost, weight, desc=""):
    return {"name": name, "slug": slug, "data": {"type": "gear", "cost": cost, "weight": weight, "desc": desc}}

