def _m(name, slug, size, type_, cr, ac, hp, speed, abil, actions, traits=None, senses="", langs="", extra=None):
    d = {"size": size, "type": type_, "cr": cr, "ac": ac, "hp": hp, "speed": speed, "abilities": dict(zip(["str", "dex", "con", "int", "wis", "cha"], abil)), "actions": actions, "traits": traits or [], "senses": senses, "languages": langs}
    if extra:
        d.update(extra)
    return {"name": name, "slug": slug, "data": d}

