def all_entries():
    out = []
    for r in RACES:
        out.append(("race", r["slug"], r["name"], r["data"]))
    for c in CLASSES:
        out.append(("class", c["slug"], c["name"], c["data"]))
    for b in BACKGROUNDS:
        out.append(("background", b["slug"], b["name"], b["data"]))
    for i in ITEMS:
        out.append(("item", i["slug"], i["name"], i["data"]))
    for s in SPELLS:
        out.append(("spell", s["slug"], s["name"], s["data"]))
    for m in MONSTERS:
        out.append(("monster", m["slug"], m["name"], m["data"]))
    for n, s, t in CONDITIONS:
        out.append(("condition", s, n, {"desc": t}))
    for n, s, t in FEATS:
        out.append(("feat", s, n, {"desc": t}))
    return out
